    if (action === 'load') { const all = await loadCampaigns(userId); const sd = buildSegmentData(all); const results = {}; for (const [seg, camps] of Object.entries(sd)) results[seg] = runAlgorithms(camps, sector); const recs = Object.entries(results).sort((a, b) => ({ 'Complaint risk': 5, 'Damaged': 4, 'Fatigue building': 3, 'Cooling': 2, 'Recovering': 1 }[b[1].sentiment.state] || 0) - ({ 'Complaint risk': 5, 'Damaged': 4, 'Fatigue building': 3, 'Cooling': 2, 'Recovering': 1 }[a[1].sentiment.state] || 0)).slice(0, 3).map(([seg, d]) => ({ segment: seg, verdict: d.sentiment.verdict, action: d.sentiment.action, type: d.freqTolerance.recommendedType, date: d.freqTolerance.optimalNextSend, state: d.sentiment.state, capital: d.capital, unsubRate: d.fingerprint?.selfBaseline, benchRate: d.bench?.unsubNormal, excessUnsubs: d.subscriberLoss?.totalExcessUnsubs })); const snaps = await getSnapshotsBySegment(userId); const cm = {}, pm = {}; for (const seg of Object.keys(snaps)) { const l = snaps[seg]; if (l[0]) cm[seg] = { state: l[0].state, capital: l[0].capital, avgUnsubRate: l[0].avgUnsubRate, excessUnsubs: l[0].excessUnsubs }; if (l[1]) pm[seg] = l[1]; } const ch = Object.keys(cm).length ? buildChangeComparison(cm, pm) : null; return res.status(200).json({ success: true, segments: results, recommendations: recs, sector, changes: ch }); }

